<template>
  <div class="address-list">
    <div class="list">
      <div class="item"  v-for="(item, index) in list" :key="index" @click="select(item)">
        <div class="address">{{ item.adress + ' ' + item.detail }}</div>
        <div>
          <span class="name">{{ item.name }}</span>
          <span>{{ item.phone }}</span>
        </div>
      </div>
      <div class="item unable" v-for="(item, index) in unableList" :key="index">
        <div class="address">{{ item.adress + ' ' + item.detail }}</div>
        <div>
          <span class="name">{{ item.name }}</span>
          <span>{{ item.phone }}</span>
        </div>
        <div class="unable-img"><img src="./imgs/unable.png"></div>
      </div>
    </div>
    <div class="bottom-btn" @click="addAddress"><i class="icon iconfont">&#xe600;</i>添加常用地址</div>
  </div>
</template>

<script>
export default {
  name: 'AddressInput',
  data () {
    return {
      list: [],
      cityId: '',
      unableList: [] // 不在配送范围的地址，以cityID区分
    }
  },
  created () {
    this.cityId = this.$globalData.addressCityId
    this.getAddressList()
  },
  methods: {
    select (value) {
      value.point = {
        lng: value.lng,
        lat: value.lat
      }
      this.$globalData[this.$globalData.addressType] = value
      this.$router.go(-1)
    },
    // 获取地址列表
    async getAddressList () {
      try {
        let res = await this.$api.getAddressList({ longlatType: 'baidu' })
        if (res.errorMsg) {
          return
        }
        console.log('3333333333', res)

        if (this.cityId != '') {
          res.forEach((item, index, arr) => {
            item.city == this.cityId ? this.list.push(item) : this.unableList.push(item)
          })
        } else {
          this.list = res
        }
      } catch (e) {
        console.log('获取地址列表出错 getAddressList')
      }
    },
    addAddress () {
      this.$globalData.addressAddType = 2
      this.$globalData.addressInput = ''
      this.$router.push('/addaddress')
    }
  }
}
</script>

<style lang="stylus" scoped>
  .address-list
    height 100%
    overflow hidden
    position relative
    background #f2f2f2
    .list
      height -webkit-calc(100% - 50px)
      height calc(100% - 50px)
      overflow-y auto
      .item
        padding 12px 15px
        font-size 15PX
        border-bottom 1PX solid #dfdfdf
        line-height 1.8
        color #666
        position relative
        background #fff
        &.unable
          background #f2f2f2
        &:last-child
          border-bottom none
        &>div
          ellipsis(1)
        .address
          color #000
          font-size 16PX
        .name
          margin-right 10px
        .unable-img
          position absolute
          right 15px
          top 0
          bottom 0
          z-index 2
          img
            height 80%
            margin-top 12%
    .bottom-btn
      position absolute
      bottom 0
      left 0
      right 0
      font-size 16px
      text-align center
      height 50px
      line-height 50px
      border-top 1PX solid #ccc
      background #fff
      .icon
        color $color-main
        font-size 18px
        margin-right 5px
</style>
